class AutoCADErrorHandler:
    """Centralized error handling for AutoCAD operations."""

    @staticmethod
    def handle_autocad_error(error, context=""):
        """Handle AutoCAD-specific errors."""
        if isinstance(error, com_error):
            hresult = error.hresult
            if hresult == -2147352567:
                return "Invalid parameters provided to AutoCAD operation"
            elif "connection" in str(error).lower():
                return "Failed to connect to AutoCAD. Please ensure AutoCAD is running."
        return f"AutoCAD operation failed: {str(error)}"

def safe_autocad_operation(self):
    """Example of comprehensive error handling."""
    try:
        # Validate inputs first
        center = self.validate_coordinates(self.center_entry.get())
        radius = self.validate_radius(self.radius_entry.get())

        # Perform operation
        with self.com_lock:
            result = self.acad_app.ActiveDocument.ModelSpace.AddCircle(
                self.convert_to_variant(center), radius
            )

        return result

    except ValueError as e:
        raise ValueError(f"Input validation failed: {e}")
    except com_error as e:
        raise RuntimeError(AutoCADErrorHandler.handle_autocad_error(e, "circle creation"))
    except Exception as e:
        raise RuntimeError(f"Unexpected error: {e}")

